CREATE TABLE finance_chart_of_accounts (id uuid PRIMARY KEY, company_id uuid NOT NULL UNIQUE, name varchar(200) NOT NULL);
CREATE TABLE finance_account (id uuid PRIMARY KEY, company_id uuid NOT NULL, account_code varchar(80) NOT NULL, name varchar(240) NOT NULL, account_type varchar(24) NOT NULL, parent_account_id uuid REFERENCES finance_account(id), postable boolean NOT NULL, active boolean NOT NULL, CONSTRAINT uq_finance_account_code UNIQUE(company_id, account_code), CONSTRAINT ck_finance_account_type CHECK(account_type IN ('ASSET','LIABILITY','EQUITY','REVENUE','EXPENSE')));
CREATE TABLE finance_fiscal_year (id uuid PRIMARY KEY, company_id uuid NOT NULL, fiscal_year_code varchar(80) NOT NULL, starts_on date NOT NULL, ends_on date NOT NULL, closed boolean NOT NULL, CONSTRAINT uq_finance_fiscal_year UNIQUE(company_id,fiscal_year_code), CONSTRAINT ck_finance_fiscal_dates CHECK(ends_on >= starts_on));
CREATE TABLE finance_accounting_period (id uuid PRIMARY KEY, fiscal_year_id uuid NOT NULL REFERENCES finance_fiscal_year(id), period_code varchar(80) NOT NULL, starts_on date NOT NULL, ends_on date NOT NULL, closed boolean NOT NULL, CONSTRAINT uq_finance_period UNIQUE(fiscal_year_id,period_code), CONSTRAINT ck_finance_period_dates CHECK(ends_on >= starts_on));
CREATE TABLE finance_cost_center (id uuid PRIMARY KEY, company_id uuid NOT NULL, code varchar(80) NOT NULL, active boolean NOT NULL, CONSTRAINT uq_finance_cost_center UNIQUE(company_id,code));
CREATE TABLE finance_profit_center (id uuid PRIMARY KEY, company_id uuid NOT NULL, code varchar(80) NOT NULL, active boolean NOT NULL, CONSTRAINT uq_finance_profit_center UNIQUE(company_id,code));
CREATE TABLE finance_journal_entry (id uuid PRIMARY KEY, journal_number varchar(120) NOT NULL UNIQUE, idempotency_key varchar(160) NOT NULL UNIQUE, company_id uuid NOT NULL, branch_id uuid NOT NULL, fiscal_year_id uuid NOT NULL REFERENCES finance_fiscal_year(id), period_id uuid NOT NULL REFERENCES finance_accounting_period(id), posting_date date NOT NULL, status varchar(20) NOT NULL, reversal_of_id uuid REFERENCES finance_journal_entry(id), lock_version integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL, actor varchar(160) NOT NULL, CONSTRAINT ck_finance_journal_status CHECK(status IN ('DRAFT','POSTED','REVERSED')));
CREATE TABLE finance_journal_line (id uuid PRIMARY KEY, journal_id uuid NOT NULL REFERENCES finance_journal_entry(id), account_id uuid NOT NULL REFERENCES finance_account(id), debit numeric(19,6) NOT NULL, credit numeric(19,6) NOT NULL, cost_center_id uuid, profit_center_id uuid, dimension_code varchar(100), currency_id uuid, currency_amount numeric(19,6), exchange_rate_snapshot numeric(19,8), CONSTRAINT ck_finance_journal_line_amount CHECK((debit > 0 AND credit = 0) OR (credit > 0 AND debit = 0)));
CREATE TABLE finance_journal_reversal (id uuid PRIMARY KEY, original_journal_id uuid NOT NULL UNIQUE REFERENCES finance_journal_entry(id), reversal_journal_id uuid NOT NULL UNIQUE REFERENCES finance_journal_entry(id));
CREATE INDEX ix_finance_journal_company_date ON finance_journal_entry(company_id, posting_date);
